#include "th10/game/title_menu_runtime.hpp"
namespace{void Advance(TitleMenuClock&c){const float s=c.scale?*c.scale:1.f;c.previous=c.frame;if(s>.99f&&s<1.01f){++c.frame;c.elapsed+=1.f;}else{c.elapsed+=s;c.frame=(int)c.elapsed;}}}
// 0x0042CDF0 - title/practice/replay dispatcher plus four-demo attract rotation.
int TitleMenuRuntime_Update(TitleMenuRuntime*m,TitleMenuGlobals*g,const TitleMenuOps*o){
 if(m->phase==1||m->phase==2){if((g->input_mask&0x160b)!=0)g->demo_counter=0;else if(++g->demo_counter>=900){DemoReplayInfo r={};const char*n=g->demo_names[g->demo_index];if(o->load_demo(o->context,n,&r)){g->demo_index=(g->demo_index+1)%4;g->game_flags=(g->game_flags&~0x40u)|0x20u;g->stage=r.stage;g->character=r.character;g->shot=r.shot;g->previous_difficulty=g->difficulty;g->difficulty=r.difficulty;g->launch_state=12;g->attract_mode=m->phase!=1?1:0;}g->demo_counter=0;}}
 if(m->phase==0){for(int i=0;i<5;++i)o->hide_title_vm(o->context,i);o->reset_stage_ui(o->context);if(g->attract_mode==3){m->selection_count=10;m->selection=0;o->reset_selection(o->context);o->set_phase(o->context,15);o->open_view(o->context,91);o->close_view(o->context,91);if(m->owner_flags)*m->owner_flags|=2u;g->attract_mode=1;}else{if((g->game_flags&0x20u)==0)o->play_title_music(o->context);else g->difficulty=g->previous_difficulty;g->game_flags&=~0x20u;if(g->attract_mode==0){o->set_phase(o->context,1);g->attract_mode=1;}else if(g->attract_mode==1){if(g->difficulty==4){m->selection_count=2;m->selection=m->selection_count>1?1:0;}o->set_phase(o->context,2);o->open_view(o->context,91);if(m->owner_flags)*m->owner_flags|=2u;}else if(g->attract_mode==2){m->selection_count=10;m->selection=3;o->reset_selection(o->context);o->set_phase(o->context,12);o->open_view(o->context,91);o->close_view(o->context,91);if(m->owner_flags)*m->owner_flags|=2u;g->attract_mode=1;}}}else o->dispatch_phase(o->context,m->phase,m);
 Advance(m->clock);return 1;}
